$lang['map_introtext1'] = 'පහත සිතියම සෙවුම් ප්‍රතිඵලයෙන් භූගෝලීය ස්ථානයක් ඇති සම්පත් පෙන්වයි. සලකුණු වර්ණය සම්පත් වර්ගය හෝ අභිරුචි මූලාකෘති ක්ෂේත්‍රයකට (සිතියමේ යටතේ යතුර) අනුව සකසයි. සලකුණු එකිනෙකට ආවරණය වීමේදී, කොළ පැහැති සමූහනයක් සහ සමූහිත සලකුණු ගණනක් දක්වයි, විශාලනය කරන්න හෝ සමූහයක් දෙවරක් ක්ලික් කරන්න. සම්පතකට සම්බන්ධ සලකුණක් ක්ලික් කිරීමෙන් පෙරදසුනක් සහිත පූප්පුවක් පෙන්වයි. පෙරදසුන ක්ලික් කිරීමෙන් සම්පත සඳහා ජනේලයක් විවෘත වේ. සලකුණ මත මවුස් තබා භූගෝලීය සන්ධාන දර්ශනය කරන්න. ඉහළ දකුණු සිතියම් බොත්තමෙන් මූලික සිතියම වෙනස් කරන්න. පහළ වම් සිතියම් බොත්තමෙන් සිතියම PNG ගොනුවක් ලෙස සුරකින්න.';
$lang['edit_map_introtext'] = 'අවශ්‍ය සිතියම් දර්ශනයට පැන හා විශාලනය කරන්න, පසුව සම්පතේ ස්ථානය සොයා සිතියම මත ක්ලික් කරන්න. නවතම භූගෝලීය ස්ථානය සුරකින්න, පසුව \'සම්පත් සංස්කරණයට හෝ එකතුව භූගෝලීය කිරීමට ආපසු යන්න\' ක්ලික් කරන්න. විශේෂ ස්ථානයක් හෝ භූගෝලීය ලක්ෂණයක් සෙවීමට ඉහළ දකුණු සෙවුම් බොත්තම භාවිතා කරන්න. ඉහළ දකුණු සිතියම් ස්ථර බොත්තමෙන් මූලික සිතියම වෙනස් කරන්න. පහළ වම් සිතියම් බොත්තමෙන් සිතියම PNG ගොනුවක් ලෙස සුරකින්න.';
