$lang['oj_recreate_previews_refs_help'] = 'මෙම විකල්පය සකස් කිරීමෙන් සැකසීම සඳහා භාවිතා වන යොමුකිරීම් (සම්පත් හෝ සංග්‍රහ යොමුකිරීම්) පාලනය වේ. වලංගු ආදාන අතර කොමාවෙන් වෙන් කළ ලැයිස්තු, පරාස සහ වයිල්ඩ්කාඩ් ඇතුළත් වේ. උදාහරණයක් ලෙස * සියලු යොමුකිරීම් සැකසීමට, 1-100 පළමු 100 යොමුකිරීම් සැකසීමට, 101-* 101 සහ ඊට පසු යොමුකිරීම් සැකසීමට, 1,3,5 යොමුකිරීම් 1, 3 සහ 5 සැකසීමට යොදා ගත හැක. මෙය අවශ්‍ය යොමුකිරීම් නිවැරදිව ඉලක්ක කිරීමට එකතු කළ හැක, උදාහරණයක් ලෙස 1,5-10,15-* යොමුකිරීම් 1, 5 සිට 10 දක්වා සහ 15 සිට ඉදිරියට ඉලක්ක කරයි.';
$lang['oj_recreate_previews_use_existing_help'] = 'මෙම විකල්පය සකස් කිරීමෙන් සම්පත් මත අතින් ප්‍රතිස්ථාපිත පෙරදසුන් රඳවා ගැනීමට උත්සාහ කරයි. භාවිතා නොකළහොත්, අතින් උඩුගත කළ පෙරදසුන් මුල් ගොනුවෙන් ලබා ගත් පෙරදසුන් මඟින් ප්‍රතිස්ථාපිත වේ.';
