$lang['collection_email__introtext'] = 'කරුණාකර පහත පෝරමය සම්පූර්ණ කරන්න.<br />ලබන්නන්ට ගොනු ඇමුණුම් වෙනුවට එකතු කිරීම් වෙත සබැඳි අඩංගු විද්‍යුත් තැපෑලක් හෝ පද්ධති පණිවිඩයක් ලැබෙනු ඇත. එවිට ඔවුන්ට සුදුසු සම්පත් තෝරා බාගත කළ හැක.';

$lang['information-geomapping'] = 'මෙම ක්ෂේත්‍රයේ භූ-ස්ථානය අක්ෂාංශය, දේශාංශය හෝ දෙකම ලෙස ගබඩා කරන්න.<br />එකම ක්ෂේත්‍රයක් දෙකම ලෙස හෝ එක් ක්ෂේත්‍රයක් අක්ෂාංශය සඳහා සහ වෙනත් ක්ෂේත්‍රයක් දේශාංශය සඳහා සකස් කළ හැකිය.<br />එය එක් පේළි පෙළ පෙළ ක්ෂේත්‍ර සඳහා පමණි.';
$lang['accountdoesnotexist'] = 'මෙම පරිශීලක ගිණුම නොපවතී.<br />ඔබ මෙම පිටුවට පරිශීලක පණිවිඩ ප්‍රදේශයේ සබැඳියක් හරහා පැමිණ ඇත්නම්, වෙනත් පරිපාලකයෙකු දැනටමත් ගිණුම් ඉල්ලීමක් සැලසූවක් සහ මෙම ගිණුම ඉවත් කර ඇති බව කරුණාවෙන් සලකන්න.';
$lang['contactsheetintrotext'] = 'කරුණාකර ඔබගේ සම්බන්ධතා පත්‍රිකා PDF සඳහා ඔබ කැමති වින්‍යාස විකල්ප තෝරන්න. ඔබගේ විකල්ප වෙනස් කළ විට පෙරදසුන ස්වයංක්‍රීයව යාවත්කාලීන වේ. ඔබ තෝරාගත් මූලාශ්‍ර දත්ත ක්ෂේත්‍ර හෝ සංග්‍රහයේ සම්පත් අනුපිළිවෙළ වෙනස් කළහොත්, "පෙරදසුන යාවත්කාලීන කරන්න" බොත්තම ඔබා යාවත්කාලීන කළ යුතුය.<br />සූදානම් වූ විට, "තනන්න" ඔබා ඔබගේ සම්බන්ධතා පත්‍රිකා PDF ජනනය කර බාගත කරන්න.';
$lang['exportdata-instructions'] = 'මෙය ඔබගේ පද්ධතියෙන් පද්ධති වින්‍යාස දත්ත අපනයනය කරයි, ගැටළු විසඳීම සඳහා. සියලු දත්ත (ක්ෂේත්‍ර විකල්ප, පරිශීලක නාම, ඊමේල් සහ මූලාශ්‍ර දත්ත ආදී) ඔබගේ සේවාදායක පරිපාලකයාගේ අවසරය නොමැතිනම් අසත්‍ය කරනු ලැබේ.</br>ඔබ අපනයනය කිරීමට අවශ්‍ය තොරතුරු තෝරා \'අපනයනය කරන්න\' ක්ලික් කරන්න. අපොෆ්ලයින් වැඩක් නිර්මාණය වන අතර ඔබගේ බාගත කිරීම සූදානම් වූ විට දැනුම් දීමක් ලැබේ.';
$lang['cannotemailpassword'] = 'ඔබට පරිශීලකයාට ඔවුන්ගේ පවතින මුරපදය ඊමේල් කළ නොහැක, එය ගබඩා කර නොමැති බැවින් (එහි cryptographic hash එකක් ගබඩා කර ඇත).<br /><br />ඔබ ඉහත \'උපදෙස්\' බොත්තම භාවිතා කළ යුතුය, එය නව මුරපදයක් ජනනය කර ඊමේල් ක්‍රියාවලිය සක්‍රීය කරයි.';
