$lang['tagcloudtext'] = 'මිනිසුන් මූලාශ්‍ර ටැග් කිරීමට භාවිතා කළ මූලාශ්‍ර දත්ත පද මොනවාද? වචනයක් වැඩි වතාවක් භාවිතා කළ විට, එය වලාකුළේ විශාල ලෙස පෙන්වයි.<br /><br />පහත ඇති ඕනෑම වචනයක් මත ක්ලික් කර සෙවීම ක්‍රියාත්මක කළ හැක.';
