$lang['team_research__introtext'] = '\'පර්යේෂණ ඉල්ලීම්\' සංවිධානය කර කළමනාකරණය කරන්න. <br /><br />\'පර්යේෂණය සංස්කරණය කරන්න\' තෝරා ඉල්ලීමේ විස්තර සමාලෝචනය කර පර්යේෂණය කණ්ඩායම් සාමාජිකයෙකුට පවරන්න. පෙර සංග්‍රහයක් මත පර්යේෂණ ඉල්ලීමක් පදනම් කර ගැනීමට \'සංස්කරණය\' තිරයේ සංග්‍රහ ID ඇතුළත් කළ හැකිය. <br /><br />පර්යේෂණ ඉල්ලීම පවරා ඇති විට, \'සංග්‍රහය සංස්කරණය කරන්න\' තෝරා පර්යේෂණ ඉල්ලීම \'පෙරනිමි සංග්‍රහය\' පැනලයට එක් කරන්න. සාමාන්‍ය මෙවලම් භාවිතයෙන් පර්යේෂණයට සම්පත් එක් කළ හැකිය. <br /><br />පර්යේෂණය අවසන් වූ විට, \'පර්යේෂණය සංස්කරණය කරන්න\' තෝරා, තත්ත්වය \'අවසන්\' ලෙස වෙනස් කරන්න. පරිශීලකයාට ඊමේල් පණිවිඩයක් ස්වයංක්‍රීයව යවනු ලැබේ. ඊමේල් පණිවිඩයේ පර්යේෂණයට සබැඳියක් ඇත සහ එය ඔවුන්ගේ \'පෙරනිමි සංග්‍රහය\' පැනලයට ස්වයංක්‍රීයව එක් කර ඇත.';
