$lang['themes__manage'] = 'අන්තර්ජාලය මත ලබා ගත හැකි විශේෂිත සංග්‍රහ සංවිධානය සහ සංස්කරණය කරන්න. විශේෂිත සංග්‍රහ යනු විශේෂිත ලෙස ප්‍රවර්ධනය කරන ලද සංග්‍රහ වේ. <br /><br /> <strong>1 නව විශේෂිත සංග්‍රහයක් යටතේ නව ඇතුළුවීමක් සාදන්න - සංග්‍රහයක් සාදන්න</strong><br /> ප්‍රධාන ඉහළ මෙනුවෙන් <strong>මගේ සංග්‍රහ</strong> තෝරා ගන්න සහ නව <strong>පොදු</strong> සංග්‍රහයක් පිහිටුවන්න. පිහිටුවීමේදී විශේෂිත සංග්‍රහ නම ඇතුළුවීමට අමතක නොවන්න. වර්තමාන විශේෂිත සංග්‍රහයක් යටතේ සංග්‍රහය සමූහගත කිරීමට පවතින විශේෂිත සංග්‍රහ නමක් භාවිතා කරන්න (ඔබ එය නිවැරදිව ටයිප් කරන බවට විශ්වාස කරන්න), නැතහොත් නව මාතෘකාවක් තෝරා නව විශේෂිත සංග්‍රහයක් සාදන්න. පරිශීලකයන්ට විශේෂිත සංග්‍රහ වලින් සම්පත් එකතු/ඉවත් කිරීමට කිසිවිටෙකත් ඉඩ නොදිය යුතුය. <br /> <br /><strong>2 විශේෂිත සංග්‍රහයක් යටතේ පවතින ඇතුළුවීමක අන්තර්ගතය සංස්කරණය කිරීමට </strong><br /> <strong>සංග්‍රහය සංස්කරණය කරන්න</strong> තෝරන්න. එම සංග්‍රහයේ අයිතම <strong>මගේ සංග්‍රහ</strong> පැනලයේ තිරයේ පහළින් පෙනී යනු ඇත. සම්පත් සංස්කරණය, ඉවත් කිරීම හෝ එකතු කිරීම සඳහා සාමාන්‍ය මෙවලම් භාවිතා කරන්න. <br /> <br /><strong>3 විශේෂිත සංග්‍රහයක් නම වෙනස් කිරීමට හෝ සංග්‍රහයක් වෙනත් විශේෂිත සංග්‍රහයක් යටතේ පෙනී යාමට ගමන් කිරීමට</strong><br /> <strong>ගුණාංග සංස්කරණය කරන්න</strong> තෝරන්න සහ විශේෂිත සංග්‍රහ කාණ්ඩය හෝ සංග්‍රහ නම සංස්කරණය කරන්න. වර්තමාන විශේෂිත සංග්‍රහයක් යටතේ සංග්‍රහය සමූහගත කිරීමට පවතින විශේෂිත සංග්‍රහ නමක් භාවිතා කරන්න (ඔබ එය නිවැරදිව ටයිප් කරන බවට විශ්වාස කරන්න), නැතහොත් නව මාතෘකාවක් තෝරා නව විශේෂිත සංග්‍රහයක් සාදන්න. <br /> <br /><strong>4 විශේෂිත සංග්‍රහයකින් සංග්‍රහයක් ඉවත් කිරීමට </strong><br /> <strong>ගුණාංග සංස්කරණය කරන්න</strong> තෝරන්න සහ විශේෂිත සංග්‍රහ කාණ්ඩය පෙට්ටියේ වචන මකන්න.';
